solution.code:
function intersection(a, b) {
  return a.filter(function (x, i) {
    return b.indexOf(x) !== -1 && a.indexOf(x) === i;
  });
}

console.log(intersection([1, 2, 2, 3, 4], [2, 4, 4, 6]));
